export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = Math.max(0, Math.min(time, T));
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss'; else if (t >= T - 1e-9) st = 'Back at launch height'; else if (Math.abs(t - ta) < 0.005) st = 'At the top'; else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 30, w: 300, h: 380, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 30, w: 300, h: 380, title: 'Velocity over time', state: '' }));
  const y0 = 380, sy = 280 / 2.2;
  o.push(sdk.axis('axis.h', { x: 60, y: y0, length: 280, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const by = y0 - y * sy;
  o.push(sdk.circle('ball.toss', 150, by, 26));
  o.push(...sdk.vector('vec.v', { x: 150, y: by - 20 * 0 }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 190, y: by }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(sdk.callout(215, 100, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = sdk.sample(s => u - g * s * T / 24 * 0 - g * s, 0, 1, 1);
  const n = 20, full = [], cur = [];
  for (let i = 0; i <= n; i++) { const s = 1.8 * i / n; if (s <= T + 1e-9) full.push({ x: s, y: u - g * s }); }
  const k = 12;
  for (let i = 0; i <= k; i++) { const s = t * i / k; cur.push({ x: s, y: u - g * s }); }
  const series = [{ label: 'v(t)', kind: 'line', points: cur }];
  if (full.length > 1) series.push({ label: 'full', kind: 'line', points: full });
  o.push(sdk.plot('plot.vt', { x: 345, y: 60, w: 275, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 480, 400, 'slope a = -g = ' + sdk.format(-g, 1), { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
